scripts.linear_congruential:
def solve(inputs: dict) -> float:
    x = int(inputs['SEED'])
    a = int(inputs['A'])
    b = int(inputs['B'])
    m = int(inputs['M'])
    k = int(inputs['K'])
    for _ in range(k):
        x = (a * x + b) % m
    return float(x)

scripts.sum_of_squares:
def solve(inputs: dict) -> float:
    # Extract values - passed as v1, v2, v3
    vals = [inputs[k] for k in sorted(inputs.keys())]
    result = sum(v**2 for v in vals)
    print(f"Result: {result}")
    return float(result)

